<?php
namespace App\Http\Controllers\Api\Dashboard;
use App\Http\Controllers\Controller; use App\Models\Warehouse; use App\Models\WarehouseStock; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class WarehouseController extends Controller { public function index(){return response()->json(Warehouse::with('stocks.product')->orderBy('name')->get());} public function store(Request $r){$v=$r->validate(['code'=>'required|string|max:50|unique:warehouses,code','name'=>'required|string|max:255','address'=>'nullable|string','phone'=>'nullable|string|max:50']);return response()->json(Warehouse::create($v),201);} public function update(Request $r,Warehouse $warehouse){$v=$r->validate(['code'=>'required|string|max:50|unique:warehouses,code,'.$warehouse->id,'name'=>'required|string|max:255','address'=>'nullable|string','phone'=>'nullable|string|max:50','is_active'=>'boolean']);$warehouse->update($v);return response()->json($warehouse);} public function stock(Warehouse $warehouse){return response()->json($warehouse->stocks()->with('product')->orderByDesc('quantity')->get());}
 public function transfer(Request $r){$v=$r->validate(['product_id'=>'required|exists:inventory_products,id','from_warehouse_id'=>'required|exists:warehouses,id|different:to_warehouse_id','to_warehouse_id'=>'required|exists:warehouses,id','quantity'=>'required|integer|min:1','reference'=>'nullable|string|max:100','reason'=>'nullable|string|max:255']);return DB::transaction(function()use($v,$r){$from=WarehouseStock::lockForUpdate()->firstOrCreate(['warehouse_id'=>$v['from_warehouse_id'],'inventory_product_id'=>$v['product_id']],['quantity'=>0,'reserved_quantity'=>0]);if($from->quantity<$v['quantity'])abort(422,'Stock insuffisant dans l’entrepôt source.');$to=WarehouseStock::lockForUpdate()->firstOrCreate(['warehouse_id'=>$v['to_warehouse_id'],'inventory_product_id'=>$v['product_id']],['quantity'=>0,'reserved_quantity'=>0]);$from->decrement('quantity',$v['quantity']);$to->increment('quantity',$v['quantity']);return response()->json(['message'=>'Transfert effectué.','source'=>$from->fresh('warehouse','product'),'destination'=>$to->fresh('warehouse','product')],201);});}}
